/* 📖 Grammaticabegrippen: de Turkse blokken (cursus Nederlands→Turks). Komt bovenop js/begrippen.js via S.Begrippen.add.
   Elk blok: { n: Turkse naam, html, ex, uz (uitzonderingen MÉT reden), table } en optioneel t / k / gen (eigen titel, korte
   omschrijving en algemene uitleg als die van het Spaans afwijkt) en a (extra zoekpatronen voor tikbare woorden).
   Onderaan: begrippen die alleen in het Turks bestaan (klinkerharmonie, naamval, achtervoegsel, brede tijd …). */
(function (S) {
  'use strict';
  if (!S.Begrippen || !S.Begrippen.add) return;
  S.Begrippen.add('tr', {
    /* ================= Woordsoorten ================= */
    zn: { n: 'isim (ad)', gen: 'Een <b>zelfstandig naamwoord</b> is een woord voor een ding, persoon, dier, plaats of idee: <i>tafel, moeder, kat, Istanbul, geluk</i>. <b>Test:</b> past er <i>de</i>, <i>het</i> of <i>een</i> voor? Dan is het bijna altijd een zelfstandig naamwoord.',
      html: 'Een Turks zelfstandig naamwoord heeft <b>geen geslacht en geen lidwoord</b>: <i>ev</i> is huis, het huis of een huis. Alles wat het Nederlands met losse woordjes zegt (in, van, mijn, meer dan één) plak je er als <b>achtervoegsel</b> achter: <i>ev-ler-im-de</i> = in mijn huizen.',
      ex: [['ev', '(het) huis'], ['evler', 'huizen'], ['evim', 'mijn huis'], ['evimde', 'in mijn huis']] },
    lidwoord: { n: 'tanımlık (artikel)',
      html: 'Het Turks heeft <b>geen lidwoord</b>. <i>Kitap</i> betekent boek, het boek of een boek; de zin maakt duidelijk wat je bedoelt. Wil je "een" benadrukken, dan zeg je <b>bir</b> (één): <i>bir kitap</i>. Met een bijvoeglijk naamwoord staat <i>bir</i> ertussen: <i>güzel <b>bir</b> ev</i> (een mooi huis). "De/het" hoor je alleen bij het lijdend voorwerp, aan de uitgang <b>-i</b>: <i>Kitab<b>ı</b> okudum</i> (ik las hét boek).',
      ex: [['Kitap okuyorum.', 'Ik lees een boek / ik ben aan het lezen.'], ['Bir kahve, lütfen.', 'Een koffie, alstublieft.'], ['güzel bir şehir', 'een mooie stad'], ['Kitabı okudum.', 'Ik heb het boek gelezen.']] },
    bn: { n: 'sıfat', k: 'Zegt hoe iets of iemand is: groot, mooi, Turks.',
      html: 'Het bijvoeglijk naamwoord staat <b>vóór</b> het zelfstandig naamwoord en <b>verandert nooit</b>: <i>büyük ev, büyük evler</i>. Veel bijvoeglijke naamwoorden maak je zelf met <b>-li</b> (met) en <b>-siz</b> (zonder): <i>şeker<b>li</b></i> (met suiker), <i>şeker<b>siz</b></i> (zonder suiker).',
      ex: [['büyük bir ev', 'een groot huis'], ['büyük evler', 'grote huizen'], ['Ev büyük.', 'Het huis is groot.'], ['şekerli çay, şekersiz kahve', 'thee met suiker, koffie zonder suiker']] },
    ww: { n: 'fiil (eylem)',
      html: 'Het Turkse werkwoord staat <b>aan het eind van de zin</b>. Alles zit in één woord: stam + tijd + persoon. <i>Gel-iyor-um</i> = ik kom. Een los woord voor ik, jij of hij is daardoor meestal niet nodig.',
      ex: [['gelmek', 'komen'], ['Geliyorum.', 'Ik kom.'], ['Gelmedin.', 'Je bent niet gekomen.'], ['Gelecek misiniz?', 'Komen jullie / komt u?']] },
    bw: { n: 'zarf (belirteç)',
      html: 'Een bijvoeglijk naamwoord kun je in het Turks <b>zonder verandering</b> als bijwoord gebruiken: <i>güzel bir şarkı</i> (een mooi lied), <i>güzel söylüyor</i> (ze zingt mooi). Soms komt er <b>-ce</b> achter: <i>yavaş<b>ça</b></i> (langzaam). Het bijwoord staat vóór het werkwoord.',
      ex: [['Çok güzel konuşuyorsun.', 'Je praat heel mooi.'], ['Yavaşça yürüdü.', 'Hij liep langzaam.'], ['Hemen geliyorum.', 'Ik kom meteen.'], ['Bugün evdeyim.', 'Vandaag ben ik thuis.']] },
    vnw: { n: 'zamir (adıl)',
      html: 'Turkse voornaamwoorden krijgen dezelfde <b>naamvallen</b> als zelfstandige naamwoorden: <i>ben, beni, bana, bende, benden, benim</i>. Als onderwerp laat je ze meestal weg, omdat de uitgang van het werkwoord al zegt wie het is.',
      ex: [['Ben geldim.', 'Ík ben gekomen (met nadruk).'], ['Geldim.', 'Ik ben gekomen.'], ['Bunu istiyorum.', 'Ik wil dit.'], ['Kim geldi?', 'Wie is er gekomen?']] },
    pers: { n: 'kişi zamiri',
      html: 'De persoonlijke voornaamwoorden zijn <b>ben, sen, o, biz, siz, onlar</b>. <i>O</i> is hij, zij én het: het Turks maakt geen verschil. Je gebruikt ze als onderwerp alleen voor <b>nadruk of contrast</b>: <i><b>Ben</b> gidiyorum, <b>sen</b> kalıyorsun</i>.',
      table: [['', 'wie', '-i (lijdend vw.)', '-e (naar/aan)', 'van'], ['ik', 'ben', 'beni', 'bana', 'benim'], ['jij', 'sen', 'seni', 'sana', 'senin'], ['hij / zij / het', 'o', 'onu', 'ona', 'onun'], ['wij', 'biz', 'bizi', 'bize', 'bizim'], ['jullie / u', 'siz', 'sizi', 'size', 'sizin'], ['zij', 'onlar', 'onları', 'onlara', 'onların']],
      ex: [['Ben Hollandalıyım.', 'Ik ben Nederlander.'], ['O geliyor.', 'Hij / zij komt.'], ['Seni seviyorum.', 'Ik hou van je.'], ['Bana ver.', 'Geef het aan mij.']],
      uz: [['bana, sana', 'Je verwacht <i>bene</i> en <i>sene</i>, maar het is <b>bana</b> en <b>sana</b>. <b>Waarom?</b> De oude uitgang was <i>-ga</i> (<i>ben-ga</i>). Die harde g trok de klinker naar achteren (e werd a) en verdween daarna zelf. Bij <i>ona, bize, size</i> is er niets aan de hand.'],
        ['benim, bizim', 'De van-vorm is bij <i>ben</i> en <i>biz</i> <b>-im</b> (<i>benim, bizim</i>), niet -in zoals bij <i>senin, onun</i>. <b>Waarom?</b> De <i>n</i> werd een <i>m</i> onder invloed van de <i>b</i> aan het begin van het woord: twee lipklanken spreken makkelijker uit.']] },
    bez: { n: 'iyelik (sahiplik)',
      html: 'Bezit zeg je met een <b>uitgang aan het bezit</b>: <i>ev<b>im</b></i> (mijn huis), <i>ev<b>in</b></i> (jouw huis), <i>ev<b>i</b></i> (zijn/haar huis). Het losse woord <i>benim, senin, onun</i> zet je er alleen voor als je nadruk wilt: <i><b>benim</b> evim</i> (míjn huis).',
      table: [['', 'los woord', 'uitgang', 'voorbeeld'], ['mijn', 'benim', '-(i)m', 'evim · arabam'], ['jouw', 'senin', '-(i)n', 'evin · araban'], ['zijn / haar', 'onun', '-(s)i', 'evi · arabası'], ['ons', 'bizim', '-(i)miz', 'evimiz · arabamız'], ['jullie / uw', 'sizin', '-(i)niz', 'eviniz · arabanız'], ['hun', 'onların', '-leri', 'evleri · arabaları']],
      ex: [['Annem doktor.', 'Mijn moeder is arts.'], ['Adın ne?', 'Wat is je naam?'], ['Bu benim çantam.', 'Dit is míjn tas.'], ['Ali’nin arabası', 'de auto van Ali']],
      uz: [['su → suyu', '<i>Su</i> (water) krijgt <b>-yu</b>: <i>suyu, suyum</i>, niet <i>susu</i>. <b>Waarom?</b> Het woord was vroeger <i>suv</i>, met een medeklinker aan het eind. Die v is een y geworden en duikt weer op zodra er een uitgang achter komt.']] },
    aanw: { n: 'işaret zamiri',
      html: 'Het Turks heeft <b>drie</b> afstanden: <b>bu</b> (dit, bij mij), <b>şu</b> (dat daar, vaak met aanwijzen) en <b>o</b> (dat, ver weg of al genoemd). Vóór een zelfstandig naamwoord veranderen ze niet: <i>bu ev, bu evler</i>.',
      ex: [['Bu ne?', 'Wat is dit?'], ['Şu adam kim?', 'Wie is die man daar?'], ['O film çok güzeldi.', 'Die film was heel mooi.'], ['Bunu alıyorum.', 'Ik neem deze.']],
      uz: [['bunu, bunlar, burada', 'Met een uitgang komt er een <b>n</b> tussen: <i>bu<b>n</b>u, bu<b>n</b>lar, şu<b>n</b>a, o<b>n</b>da</i>. <b>Waarom?</b> Dat is de oude "voornaamwoord-n": na een aanwijzend voornaamwoord zette het Turks altijd een n vóór de naamval. Dezelfde n zie je na de bezitsuitgang: <i>evi<b>n</b>de</i>.']] },
    obj: { n: 'nesne olarak zamir',
      html: 'Het Turks heeft geen aparte woordjes zoals <i>me, hem, haar</i>. Je neemt het gewone voornaamwoord en geeft het een <b>naamval</b>: <b>beni</b> (mij, lijdend voorwerp), <b>bana</b> (aan mij). Is het duidelijk over wie of wat het gaat, dan laat je het hele woord weg.',
      ex: [['Beni duyuyor musun?', 'Hoor je me?'], ['Onu tanıyorum.', 'Ik ken hem / haar.'], ['Bana yardım et.', 'Help me.'], ['Gördün mü? – Gördüm.', 'Heb je het gezien? – Ja (ik heb het gezien).']] },
    wederk: { n: 'dönüşlü fiil · kendi', k: 'Iets wat je bij jezelf doet: zich wassen, zich aankleden. In het Turks met -in- of kendi.',
      html: 'Het Turks maakt een wederkerend werkwoord met het achtervoegsel <b>-(i)n-</b> in het werkwoord: <i>yıkamak</i> (wassen) → <i>yıka<b>n</b>mak</i> (zich wassen). Voor "zelf" gebruik je <b>kendi</b>: <i>kendim, kendin, kendisi</i>. Doe je iets met elkaar, dan is het <b>-(i)ş-</b>: <i>görmek → gör<b>üş</b>mek</i> (elkaar zien).',
      ex: [['Yıkanıyorum.', 'Ik was me.'], ['Giyindin mi?', 'Heb je je aangekleed?'], ['Kendime bir çay yaptım.', 'Ik heb voor mezelf thee gezet.'], ['Yarın görüşürüz.', 'We zien elkaar morgen.']],
      uz: [['Kendisi = hij / zij (beleefd)', '<i>Kendisi</i> betekent letterlijk "hijzelf", maar wordt ook gebruikt als beleefd woord voor <i>hij/zij</i>: <i>Müdür Bey burada mı? – Kendisi toplantıda.</i> <b>Waarom?</b> Gewoon <i>o</i> klinkt over iemand met aanzien wat kaal; <i>kendisi</i> houdt meer afstand en is daardoor beleefder.']] },
    betr: { n: 'ilgi (sıfat-fiil, ki)',
      html: 'Het Turks heeft <b>geen woord als "die" of "dat"</b>. De hele bijzin wordt een soort bijvoeglijk naamwoord dat <b>vóór</b> het zelfstandig naamwoord staat. Is het woord zelf het onderwerp, dan gebruik je <b>-en</b>: <i>gel<b>en</b> adam</i> (de man die komt). Anders <b>-diği</b> met een bezitsuitgang: <i>oku<b>duğum</b> kitap</i> (het boek dat ik lees).',
      ex: [['gelen adam', 'de man die komt'], ['okuduğum kitap', 'het boek dat ik lees / las'], ['oturduğumuz ev', 'het huis waar we wonen'], ['Almanya’da yaşayan kuzenim', 'mijn neef die in Duitsland woont']],
      uz: [['ki', 'Soms hoor je toch een los woord: <i>Biliyorum <b>ki</b> haklısın</i> (ik weet dat je gelijk hebt). <b>Waarom?</b> <i>Ki</i> is geleend uit het Perzisch en brengt de Perzische volgorde mee: eerst de hoofdzin, dan de bijzin. De echt Turkse manier is <i>Haklı olduğunu biliyorum</i>.']] },
    vraag: { n: 'soru kelimesi',
      html: 'De vraagwoorden zijn <b>ne</b> (wat), <b>kim</b> (wie), <b>nerede</b> (waar), <b>ne zaman</b> (wanneer), <b>nasıl</b> (hoe), <b>neden / niçin</b> (waarom), <b>kaç</b> (hoeveel) en <b>hangi</b> (welke). Het vraagwoord staat <b>op de plek van het antwoord</b>, meestal vlak voor het werkwoord, niet vooraan. Met een vraagwoord gebruik je <b>geen mi</b>.',
      ex: [['Adın ne?', 'Wat is je naam?'], ['Nerede oturuyorsun?', 'Waar woon je?'], ['Bu kaç lira?', 'Hoeveel lira is dit?'], ['Dün kimi gördün?', 'Wie heb je gisteren gezien?']],
      uz: [['nereye, nerede, nereden', '"Waar" verandert met de richting: <b>nereye</b> (waarheen), <b>nerede</b> (waar), <b>nereden</b> (waarvandaan). <b>Waarom?</b> <i>Nere</i> is eigenlijk een zelfstandig naamwoord ("welke plek") en krijgt dus gewoon een naamval, net als <i>ev<b>e</b>, ev<b>de</b>, ev<b>den</b></i>.']] },
    vz: { n: 'edat (ilgeç)', k: 'In, op, naar, met, van, voor. Het Turks zegt dit met een naamval of een achterzetsel.',
      html: 'Het Turks heeft <b>geen voorzetsels</b>. Wat het Nederlands vóór het woord zet, komt in het Turks <b>erachter</b>: als naamval (<i>ev<b>de</b></i> in huis, <i>ev<b>e</b></i> naar huis, <i>ev<b>den</b></i> uit huis) of als los <b>achterzetsel</b> (<i>senin <b>için</b></i> voor jou, <i>okuldan <b>sonra</b></i> na school).',
      ex: [['İstanbul’da', 'in Istanbul'], ['okula', 'naar school'], ['arkadaşımla', 'met mijn vriend'], ['masanın üstünde', 'op de tafel (letterlijk: op de bovenkant van de tafel)']] },
    vw: { n: 'bağlaç',
      html: 'De gewone voegwoorden zijn <b>ve</b> (en), <b>ama</b> (maar), <b>veya / ya da</b> (of), <b>çünkü</b> (want) en <b>de / da</b> (ook, los geschreven). Maar het Turks verbindt zinnen liever met een <b>achtervoegsel aan het werkwoord</b>: <i>gel<b>ip</b></i> (komen en …), <i>gel<b>ince</b></i> (als/zodra hij komt), <i>geldiği <b>için</b></i> (omdat hij kwam).',
      ex: [['çay ve kahve', 'thee en koffie'], ['Gelmek istiyorum ama vaktim yok.', 'Ik wil komen, maar ik heb geen tijd.'], ['Ben de geliyorum.', 'Ik kom ook.'], ['Eve gelip yemek yedim.', 'Ik kwam thuis en at.']],
      uz: [['de/da los, -de/-da vast', '<i>Ben <b>de</b> geldim</i> (ik ben ook gekomen) schrijf je los, <i>ev<b>de</b></i> (in huis) vast. <b>Waarom?</b> Het zijn twee verschillende dingen: los is het een eigen woord ("ook"), vast is het de naamval voor plaats. Het losse <i>de/da</i> wordt daarom ook nooit <i>te/ta</i>.']] },
    telw: { n: 'sayı',
      html: 'Tellen is heel regelmatig: <i>on bir</i> (10 + 1 = 11), <i>yirmi beş</i> (25), <i>iki yüz</i> (200). Rangtelwoorden krijgen <b>-(i)nci</b>: <i>bir<b>inci</b>, ik<b>inci</b>, üç<b>üncü</b></i>. Na een telwoord blijft het zelfstandig naamwoord <b>enkelvoud</b>: <i>üç elma</i>.',
      ex: [['on bir, yirmi beş', 'elf, vijfentwintig'], ['üç elma', 'drie appels'], ['ikinci kat', 'de tweede verdieping'], ['bin dokuz yüz doksan', 'negentienhonderdnegentig (1990)']],
      uz: [['ilk naast birinci', 'Voor "eerste" bestaan <i>birinci</i> en <b>ilk</b>. <i>İlk</i> is "allereerste in de tijd": <i>ilk gün</i> (de eerste dag), <i>birinci kat</i> (de eerste verdieping in een rij). <b>Waarom?</b> <i>İlk</i> is een oud apart woord voor "begin"; <i>birinci</i> is later regelmatig van <i>bir</i> gemaakt.'],
        ['yirmi, otuz, kırk, elli', 'De tientallen 20 tot en met 50 lijken niet op 2 tot en met 5. <b>Waarom?</b> Het zijn heel oude eigen woorden. Pas vanaf 60 zie je het systeem een beetje: <i>altı → altmış</i>, <i>yedi → yetmiş</i>, <i>sekiz → seksen</i>, <i>dokuz → doksan</i>.']] },
    tussenw: { n: 'ünlem',
      html: 'Turkse uitroepen die je veel hoort: <b>Aa!</b> (verbazing), <b>Eyvah!</b> (o jee), <b>Of!</b> (zucht), <b>Hadi!</b> (kom op), <b>Yaa</b> (echt? / ach), <b>Vay!</b> (wauw) en <b>Maşallah!</b> (wat mooi, bij iets wat je bewondert).',
      ex: [['Hadi, gidelim!', 'Kom op, laten we gaan!'], ['Eyvah, geç kaldım!', 'O jee, ik ben te laat!'], ['Vay, ne güzel!', 'Wauw, wat mooi!']] },

    /* ================= De zin ================= */
    onderwerp: { n: 'özne',
      html: 'Het onderwerp staat <b>vooraan</b> en heeft geen uitgang. Is het een voornaamwoord, dan laat je het meestal weg: de uitgang van het werkwoord zegt al wie het is. <i>Geliyor<b>um</b></i> = ik kom.',
      ex: [['Ayşe geliyor.', 'Ayşe komt.'], ['Geliyorum.', 'Ik kom.'], ['Çocuklar bahçede oynuyor.', 'De kinderen spelen in de tuin.']],
      uz: [['Çocuklar geliyor', 'Bij een meervoudig onderwerp mag het werkwoord in het enkelvoud blijven: <i>Çocuklar geliyor</i> (naast <i>geliyorlar</i>). <b>Waarom?</b> Het meervoud is al één keer genoemd (<i>-lar</i>), en het Turks zegt dingen liever niet dubbel.']] },
    pv: { n: 'yüklem (çekimli fiil)',
      html: 'De persoonsvorm staat <b>helemaal achteraan</b> in de zin. Ook een zin zonder werkwoord krijgt een persoonsuitgang: <i>Öğretmen<b>im</b></i> (ik ben leraar), <i>Yorgun<b>sun</b></i> (je bent moe). Het Turks heeft daar geen los woord "zijn" voor nodig.',
      ex: [['Ben her gün kahve içiyorum.', 'Ik drink elke dag koffie.'], ['Öğretmenim.', 'Ik ben leraar.'], ['Hazır mısınız?', 'Zijn jullie klaar?']] },
    lv: { n: 'nesne (belirtili / belirtisiz)',
      html: 'Het lijdend voorwerp staat vóór het werkwoord. Is het <b>bepaald</b> (hét boek, dat boek, mijn boek), dan krijgt het de uitgang <b>-i</b> (-ı, -u, -ü). Is het <b>onbepaald</b> (een boek, boeken in het algemeen), dan krijgt het niets.',
      ex: [['Kitap okuyorum.', 'Ik lees een boek / ik ben aan het lezen.'], ['Kitabı okuyorum.', 'Ik lees het boek.'], ['Bir kahve içtim.', 'Ik heb een koffie gedronken.'], ['Kahvemi içtim.', 'Ik heb mijn koffie opgedronken.']],
      uz: [['Ali’yi, seni, bunu', 'Namen en voornaamwoorden krijgen <b>altijd</b> -i: <i>Ali’<b>yi</b> gördüm, se<b>ni</b> seviyorum, bu<b>nu</b> istiyorum</i>. <b>Waarom?</b> Een naam of een voornaamwoord wijst altijd één bepaald iemand of iets aan; onbepaald kan het dus niet zijn.']] },
    mv: { n: 'dolaylı tümleç (-e hâli)',
      html: 'Het meewerkend voorwerp krijgt de uitgang <b>-e / -a</b> (na een klinker <b>-ye / -ya</b>): <i>Annem<b>e</b> çiçek verdim</i> (ik gaf mijn moeder bloemen). Dezelfde uitgang betekent ook "naar": <i>okul<b>a</b></i>.',
      ex: [['Anneme çiçek verdim.', 'Ik heb mijn moeder bloemen gegeven.'], ['Bana söyle.', 'Zeg het (tegen) mij.'], ['Ali’ye mesaj attım.', 'Ik heb Ali een bericht gestuurd.']] },
    bijzin: { n: 'yan cümle',
      html: 'Een Turkse bijzin staat <b>vóór</b> de hoofdzin en heeft meestal <b>geen voegwoord</b>. Het werkwoord van de bijzin krijgt een achtervoegsel dat het verband aangeeft: <i>gel<b>ince</b></i> (zodra hij komt), <i>gel<b>diği için</b></i> (omdat hij kwam), <i>gel<b>irse</b></i> (als hij komt), <i>gel<b>diğini</b> biliyorum</i> (ik weet dat hij kwam).',
      ex: [['Yağmur yağdığı için evde kaldım.', 'Omdat het regende, bleef ik thuis.'], ['Eve gelince seni ararım.', 'Zodra ik thuis ben, bel ik je.'], ['Geldiğini bilmiyordum.', 'Ik wist niet dat je gekomen was.'], ['Vaktin varsa gel.', 'Kom als je tijd hebt.']] },
    ontkenning: { n: 'olumsuzluk',
      html: 'Er zijn drie manieren. Een <b>werkwoord</b> krijgt <b>-me / -ma</b> direct na de stam: <i>gel<b>me</b>dim</i> (ik kwam niet). Een zin <b>zonder werkwoord</b> krijgt <b>değil</b>: <i>Hasta <b>değil</b>im</i> (ik ben niet ziek). En "er is geen / ik heb geen" is <b>yok</b>: <i>Vaktim <b>yok</b></i>.',
      ex: [['Gelmiyorum.', 'Ik kom niet.'], ['Türk değilim.', 'Ik ben niet Turks.'], ['Evde süt yok.', 'Er is geen melk in huis.'], ['Hiç kimse gelmedi.', 'Er is helemaal niemand gekomen.']],
      uz: [['gelmez, gelmem (brede tijd)', 'In de brede tijd is de ontkenning niet <i>-me + r</i> maar <b>-mez</b>: <i>gelir → gel<b>mez</b></i>, en bij ik zelfs alleen <b>-mem</b>: <i>gelmem</i>. <b>Waarom?</b> <i>-mez</i> is een oude, zelfstandige ontkennende uitgang die is blijven bestaan; hij is niet opgebouwd uit -me en -ir.'],
        ['Kimse gelmedi', 'Met <i>hiç, kimse, hiçbir şey</i> blijft het werkwoord ontkennend: <i>Kimse gel<b>me</b>di</i> (niemand kwam). <b>Waarom?</b> <i>Kimse</i> betekent eigenlijk "wie dan ook". De ontkenning zit alleen in het werkwoord; het andere woord versterkt haar.']] },
    vraagzin: { n: 'soru cümlesi (mi)',
      html: 'Een ja/nee-vraag maak je met het losse woordje <b>mi</b> (mı, mu, mü) achter het woord waar je naar vraagt, meestal het werkwoord. De woordvolgorde blijft gelijk. <i>Mi</i> volgt de klinkerharmonie en krijgt de persoonsuitgang: <i>Geliyor <b>musun</b>?</i>',
      ex: [['Geliyor musun?', 'Kom je?'], ['Hasta mısın?', 'Ben je ziek?'], ['Bu senin mi?', 'Is dit van jou?'], ['Ali mi geldi?', 'Is Áli gekomen (of iemand anders)?']],
      uz: [['Geldin mi?', 'In de verleden tijd op -di en na -se blijft de persoonsuitgang aan het werkwoord: <i>Gel<b>din</b> mi?</i>, niet <i>geldi misin</i>. <b>Waarom?</b> Deze uitgangen (-m, -n, -k) zijn vast met de tijd vergroeid. De andere uitgangen (-im, -sin, -iz) zijn eigenlijk vormen van "zijn" en hechten zich aan het laatste woord, en dat is <i>mi</i>.']] },

    /* ================= Werkwoorden ================= */
    infinitief: { n: 'mastar (-mek / -mak)',
      html: 'De Turkse infinitief eindigt op <b>-mek</b> of <b>-mak</b>: <i>gel<b>mek</b>, oku<b>mak</b></i>. Zonder -k (<b>-me / -ma</b>) wordt het een zelfstandig naamwoord dat uitgangen kan krijgen: <i>yüz<b>me</b></i> (het zwemmen), <i>gel<b>me</b>ni istiyorum</i> (ik wil dat je komt).',
      ex: [['gelmek, okumak', 'komen, lezen'], ['Gitmek istiyorum.', 'Ik wil gaan.'], ['Yüzmeyi seviyorum.', 'Ik hou van zwemmen.'], ['Sigara içmek yasak.', 'Roken is verboden.']],
      uz: [['Gelme! en gelme', '<i>Gelme</i> kan "het komen" zijn, maar ook "kom niet!". Je hoort het verschil aan de klemtoon: <i>gel<b>ME</b></i> (het komen), <i><b>GEL</b>me</i> (kom niet). <b>Waarom?</b> Het zijn twee verschillende achtervoegsels die toevallig hetzelfde klinken. De ontkenning <i>-me</i> is altijd onbeklemtoond en duwt de klemtoon naar de lettergreep ervoor.']] },
    vervoegen: { n: 'fiil çekimi',
      html: 'Een Turks werkwoord bouw je op in een vaste volgorde: <b>stam + (ontkenning) + tijd + persoon</b>. <i>gel-iyor-um</i> (ik kom), <i>gel-me-di-n</i> (je kwam niet). Bijna alle werkwoorden zijn regelmatig. Je hoeft alleen op de klinkerharmonie te letten.',
      table: [['gelmek', 'nu (-iyor)', 'verleden (-di)', 'straks (-ecek)'], ['ben', 'geliyorum', 'geldim', 'geleceğim'], ['sen', 'geliyorsun', 'geldin', 'geleceksin'], ['o', 'geliyor', 'geldi', 'gelecek'], ['biz', 'geliyoruz', 'geldik', 'geleceğiz'], ['siz', 'geliyorsunuz', 'geldiniz', 'geleceksiniz'], ['onlar', 'geliyorlar', 'geldiler', 'gelecekler']],
      ex: [['Geliyorum.', 'Ik kom.'], ['Gelmedin.', 'Je bent niet gekomen.'], ['Gelecekler.', 'Ze zullen komen.']] },
    stam: { n: 'kök (gövde) ve ek',
      html: 'De stam krijg je door <b>-mek / -mak</b> van de infinitief af te halen: <i>gelmek → <b>gel</b></i>. De kale stam is meteen ook de gebiedende wijs: <i>Gel!</i> (kom!). Achter de stam komen de uitgangen, die zich met de klinkerharmonie aanpassen aan de laatste klinker van de stam.',
      ex: [['gel-mek → gel-', 'komen → stam'], ['oku-mak → oku-', 'lezen → stam'], ['gel-di-m', 'ik kwam (stam + tijd + persoon)']],
      uz: [['git → gidiyor, et → ediyor', 'Bij een paar korte werkwoorden wordt de <b>t</b> van de stam een <b>d</b> vóór een klinker: <i>gitmek → gi<b>d</b>iyorum</i>, <i>etmek → e<b>d</b>iyorum</i>, <i>tatmak → ta<b>d</b>ıyorum</i>. <b>Waarom?</b> Tussen twee klinkers wordt een harde t makkelijk zacht. Bij deze veelgebruikte werkwoorden is dat vast geworden; bij de meeste andere (<i>atmak → atıyorum</i>) niet.']] },
    persoon: { n: 'kişi ekleri',
      html: 'Het Turks heeft twee rijtjes persoonsuitgangen. <b>Rijtje 1</b> (<i>-im, -sin, –, -iz, -siniz, -ler</i>) gebruik je na -iyor, -ecek, -miş, de brede tijd en in zinnen zonder werkwoord. <b>Rijtje 2</b> (<i>-m, -n, –, -k, -niz, -ler</i>) gebruik je na -di en -se. De 3e persoon enkelvoud heeft <b>geen uitgang</b>.',
      table: [['', 'rijtje 1', 'voorbeeld', 'rijtje 2', 'voorbeeld'], ['ben', '-im', 'geliyorum', '-m', 'geldim'], ['sen', '-sin', 'geliyorsun', '-n', 'geldin'], ['o', '–', 'geliyor', '–', 'geldi'], ['biz', '-iz', 'geliyoruz', '-k', 'geldik'], ['siz', '-siniz', 'geliyorsunuz', '-niz', 'geldiniz'], ['onlar', '-ler', 'geliyorlar', '-ler', 'geldiler']],
      ex: [['Yorgunum.', 'Ik ben moe.'], ['Yorgunsun.', 'Je bent moe.'], ['Geldik.', 'We zijn gekomen.']] },
    onregelmatig: { n: 'düzenli ve düzensiz fiiller',
      html: 'Goed nieuws: het Turks heeft <b>bijna geen onregelmatige werkwoorden</b>. Wie de klinkerharmonie en de uitgangen kent, kan elk werkwoord vervoegen. De paar afwijkingen zijn kleine klankveranderingen, geen aparte rijtjes.',
      ex: [['gelmek → geliyorum, geldim, geleceğim', 'komen: alles volgens de regel'], ['gitmek → gidiyorum', 'gaan: t wordt d'], ['demek → diyorum', 'zeggen: e wordt i']],
      uz: [['demek → diyor, yemek → yiyor', '<i>Demek</i> en <i>yemek</i> worden <b>diyor</b> en <b>yiyor</b>, en ook <i>diyecek, yiyecek</i>. <b>Waarom?</b> De stam is maar één letter plus e (<i>de-, ye-</i>). Vóór een y wordt die e smaller en klinkt als i; omdat de stam zo kort is, schrijf je dat ook zo.'],
        ['alır, gelir, olur (brede tijd)', 'Korte werkwoorden krijgen in de brede tijd <i>-er/-ar</i> (<i>yapar, gider</i>), maar dertien heel gewone werkwoorden op <i>-l, -r, -n</i> krijgen <b>-ir</b>: <i>alır, gelir, olur, verir, bilir, görür, kalır, bulur, durur, varır, vurur, sanır, ölür</i>. <b>Waarom?</b> Na l, r en n is in deze veelgebruikte woorden een oude klinker bewaard gebleven; juist woorden die je elke dag zegt, houden oude vormen het langst vast.']] },
    hulpww: { n: 'yardımcı fiil', k: 'Een werkwoord dat een ander woord helpt. In het Turks vooral etmek en olmak.',
      gen: 'Een <b>hulpwerkwoord</b> helpt een ander woord om samen één betekenis te maken. In het Nederlands zijn dat vooral <i>hebben, zijn, zullen</i>: <i>ik heb gegeten</i>.',
      html: 'Voor de tijden heeft het Turks <b>geen hulpwerkwoorden</b> nodig: dat doen de achtervoegsels. Wel maakt het met <b>etmek</b> (doen) en <b>olmak</b> (worden, zijn) van een zelfstandig naamwoord een werkwoord: <i>yardım <b>etmek</b></i> (helpen), <i>teşekkür <b>etmek</b></i> (bedanken), <i>hasta <b>olmak</b></i> (ziek worden).',
      ex: [['Teşekkür ederim.', 'Dank je wel.'], ['Bana yardım eder misin?', 'Wil je me helpen?'], ['Geçen hafta hasta oldum.', 'Vorige week ben ik ziek geworden.'], ['Rezervasyon yaptım.', 'Ik heb gereserveerd.']],
      uz: [['affetmek, kaybolmak aan elkaar', 'Meestal schrijf je twee woorden (<i>yardım etmek</i>), maar <b>affetmek</b> (vergeven), <b>kaybolmak</b> (verdwalen) en <b>hissetmek</b> (voelen) zijn één woord. <b>Waarom?</b> In deze woorden verandert het zelfstandig naamwoord zelf van vorm (<i>af → aff-</i>, <i>kayıp → kayb-</i>, <i>his → hiss-</i>). Zodra er een letter bijkomt of wegvalt, schrijf je het aan elkaar.']] },
    deelwoord: { n: 'sıfat-fiil (ortaç)', t: 'Deelwoord (-en, -diği, -miş)', k: 'Een werkwoord dat zich als bijvoeglijk naamwoord gedraagt: gelen adam, de man die komt.', a: ['en-vorm(?:en)?', 'diği-vorm(?:en)?', '-diği-vorm(?:en)?', 'sıfat-fiil'],
      gen: 'Een <b>deelwoord</b> is een vorm van het werkwoord die je als bijvoeglijk naamwoord kunt gebruiken: <i>de <b>gesloten</b> deur, het <b>spelende</b> kind</i>.',
      html: 'Het Turks gebruikt deelwoorden waar het Nederlands een bijzin met <i>die</i> of <i>dat</i> heeft. <b>-en / -an</b>: het woord doet het zelf (<i>gel<b>en</b> tren</i>, de trein die komt). <b>-diği</b> + bezitsuitgang: iemand anders doet het (<i>bekle<b>diğim</b> tren</i>, de trein waarop ik wacht). <b>-ecek</b>: nog te gebeuren (<i>oku<b>yacağım</b> kitap</i>). <b>-miş</b>: klaar (<i>piş<b>miş</b> yemek</i>, gekookt eten).',
      ex: [['gelen tren', 'de trein die komt'], ['beklediğim tren', 'de trein waarop ik wacht'], ['okuyacağım kitap', 'het boek dat ik ga lezen'], ['kırılmış bardak', 'het gebroken glas']] },
    gerundio: { n: 'zarf-fiil (ulaç)', t: 'Bijwoordelijke vorm (-ip, -erek, -ince)', k: 'Een werkwoordsvorm die twee handelingen aan elkaar knoopt: gelip, gelerek, gelince.', a: ['bijwoordelijke vorm(?:en)?', 'zarf-fiil', 'ip-vorm(?:en)?', '-ip-vorm(?:en)?'],
      gen: 'Met een <b>bijwoordelijke vorm</b> van het werkwoord knoop je twee handelingen aan elkaar zonder voegwoord. Het Nederlands doet dat soms met <i>-end</i>: <i>lach<b>end</b> liep hij weg</i>.',
      html: 'Deze vormen krijgen <b>geen tijd en geen persoon</b>; die staan alleen op het laatste werkwoord van de zin. <b>-ip</b> = en (daarna): <i>gel<b>ip</b> oturdu</i>. <b>-erek</b> = terwijl, door te: <i>koş<b>arak</b> geldi</i>. <b>-ince</b> = zodra, toen. <b>-ken</b> = terwijl. <b>-meden</b> = zonder te, voordat.',
      ex: [['Eve gelip yemek yedim.', 'Ik kwam thuis en at.'], ['Koşarak geldi.', 'Hij kwam rennend aan.'], ['Eve gelince ararım.', 'Zodra ik thuis ben, bel ik.'], ['Yemek yemeden çıktı.', 'Hij ging weg zonder te eten.']],
      uz: [['-ken verandert niet', '<i>-ken</i> blijft altijd <b>-ken</b>, ook na a, ı, o, u: <i>yapar<b>ken</b>, okur<b>ken</b></i>. <b>Waarom?</b> Het is een afgesleten los woord (<i>iken</i>, "zijnde"). Wat ooit een eigen woord was, doet niet mee aan de klinkerharmonie.']] },
    passief: { n: 'edilgen çatı',
      html: 'De lijdende vorm maak je met een achtervoegsel direct na de stam: <b>-il-</b> (<i>yap<b>ıl</b>mak</i>, gedaan worden), na een <b>l</b> wordt het <b>-in-</b> (<i>bil<b>in</b>mek</i>), na een klinker alleen <b>-n-</b> (<i>oku<b>n</b>mak</i>). Wie het doet, noem je met <b>tarafından</b>, maar meestal laat je dat weg.',
      ex: [['Bu ev 1950’de yapıldı.', 'Dit huis is in 1950 gebouwd.'], ['Burada Türkçe konuşulur.', 'Hier wordt Turks gesproken.'], ['Kapı açıldı.', 'De deur ging open / werd geopend.'], ['Kitap Orhan Pamuk tarafından yazıldı.', 'Het boek is door Orhan Pamuk geschreven.']],
      uz: [['bilinmek, okunmak', 'Na een l is het niet -il maar <b>-in</b> (<i>bulunmak, alınmak</i>), na een klinker <b>-n</b> (<i>okunmak, denmek</i>). <b>Waarom?</b> Twee keer l achter elkaar (<i>bil-il</i>) is lastig uit te spreken en te verstaan; daarom wisselt de tweede l naar n.']] },

    /* ================= Tijden en wijzen ================= */
    tijdwijs: { n: 'zaman ve kip',
      html: 'Elke Turkse tijd heeft zijn eigen achtervoegsel: <b>-iyor</b> (nu), <b>-ir</b> (gewoonlijk), <b>-di</b> (verleden, zelf gezien), <b>-miş</b> (verleden, gehoord), <b>-ecek</b> (toekomst). Je kunt er twee stapelen: <i>gel<b>iyor-du</b></i> (hij was aan het komen), <i>gel<b>ecek-ti</b></i> (hij zou komen), <i>gel<b>miş-ti</b></i> (hij was gekomen).',
      table: [['uitgang', 'betekenis', 'voorbeeld'], ['-iyor', 'nu bezig', 'geliyor'], ['-ir', 'gewoonte, algemeen', 'gelir'], ['-di', 'verleden, zelf gezien', 'geldi'], ['-miş', 'verleden, gehoord of ontdekt', 'gelmiş'], ['-ecek', 'toekomst', 'gelecek'], ['-meli', 'moeten', 'gelmeli'], ['-se', 'als', 'gelse']],
      ex: [['Geliyor.', 'Hij komt (nu).'], ['Geldi.', 'Hij is gekomen.'], ['Geliyordu.', 'Hij was aan het komen.'], ['Gelmişti.', 'Hij was gekomen.']] },
    presente: { n: 'şimdiki zaman (-iyor)', t: 'Tegenwoordige tijd (-iyor)', k: 'Wat nu gebeurt: ik kom, ik ben aan het lezen.', a: ['iyor-vorm(?:en)?', '-iyor-vorm(?:en)?', 'şimdiki zaman'],
      gen: 'De <b>tegenwoordige tijd</b> gebruik je voor wat nu gebeurt of wat nu zo is: <i>ik werk, ik woon in Istanbul</i>.',
      html: 'Het achtervoegsel is <b>-iyor</b> (-ıyor, -uyor, -üyor) plus de persoonsuitgang: <i>gel<b>iyor</b>um</i>. Je gebruikt het voor wat nu bezig is en, in spreektaal, ook voor de nabije toekomst en voor wat je tegenwoordig doet. Voor vaste gewoontes en algemene waarheden is er de brede tijd.',
      table: [['', 'gelmek', 'okumak'], ['ben', 'geliyorum', 'okuyorum'], ['sen', 'geliyorsun', 'okuyorsun'], ['o', 'geliyor', 'okuyor'], ['biz', 'geliyoruz', 'okuyoruz'], ['siz', 'geliyorsunuz', 'okuyorsunuz'], ['onlar', 'geliyorlar', 'okuyorlar']],
      ex: [['Ne yapıyorsun?', 'Wat ben je aan het doen?'], ['Kitap okuyorum.', 'Ik lees een boek.'], ['Yarın geliyorum.', 'Ik kom morgen.'], ['İstanbul’da oturuyorum.', 'Ik woon in Istanbul.']],
      uz: [['bekle → bekliyor', 'Eindigt de stam op <b>e</b> of <b>a</b>, dan verdwijnt die klinker: <i>bekle-mek → bekl<b>i</b>yor</i>, <i>anla-mak → anl<b>ı</b>yor</i>. <b>Waarom?</b> Twee klinkers mogen in het Turks niet tegen elkaar botsen. De klinker van -iyor wint, en de open e of a van de stam valt weg.'],
        ['-yor blijft -yor', 'Het stukje <b>-yor</b> verandert nooit, ook niet na e of i: <i>gel<b>iyor</b></i>, niet <i>geliyör</i>. <b>Waarom?</b> Het was vroeger een los werkwoord (<i>yorımak</i>, lopen, gaan). Een woord dat van buiten komt aangeplakt, doet niet mee aan de klinkerharmonie.']] },
    indefinido: { n: 'görülen geçmiş zaman (-di)', t: 'Verleden tijd (-di)', k: 'De gewone verleden tijd voor wat je zelf hebt gezien of gedaan: dün geldim.', a: ['di-vorm(?:en)?', '-di-vorm(?:en)?', 'verleden tijd op -di', 'gewone verleden tijd'],
      gen: 'Dit is de <b>gewone verleden tijd</b> voor iets wat afgelopen is: <i>gisteren kwam ik thuis, ik heb gegeten</i>. Het Turks maakt geen verschil tussen "ik at" en "ik heb gegeten".',
      html: 'Het achtervoegsel is <b>-di</b> (-dı, -du, -dü; na een harde medeklinker <b>-ti</b>, -tı, -tu, -tü) plus de korte persoonsuitgang: <i>gel<b>di</b>m, yap<b>tı</b>n</i>. Je gebruikt het voor iets wat je <b>zelf hebt gezien of meegemaakt</b>. Heb je het alleen gehoord, dan gebruik je -miş.',
      table: [['', 'gelmek', 'yapmak'], ['ben', 'geldim', 'yaptım'], ['sen', 'geldin', 'yaptın'], ['o', 'geldi', 'yaptı'], ['biz', 'geldik', 'yaptık'], ['siz', 'geldiniz', 'yaptınız'], ['onlar', 'geldiler', 'yaptılar']],
      ex: [['Dün sinemaya gittim.', 'Gisteren ben ik naar de bioscoop gegaan.'], ['Ne yaptın?', 'Wat heb je gedaan?'], ['Çok güzeldi.', 'Het was heel mooi.'], ['Yemek yedik.', 'We hebben gegeten.']],
      uz: [['gitti, yaptı, içti', 'Na <i>f, s, t, k, ç, ş, h, p</i> wordt de d een <b>t</b>: <i>git<b>ti</b>, yap<b>tı</b>, iç<b>ti</b></i>. <b>Waarom?</b> Na een stemloze (harde) medeklinker is een stemhebbende d lastig; de mond maakt er vanzelf een t van. Het Turks schrijft wat je hoort.']] },
    imperfecto: { n: 'şimdiki zamanın hikâyesi (-iyordu)', t: 'Was aan het … (-iyordu, -irdi)', k: 'De verleden tijd voor achtergrond en gewoontes: geliyordum, gelirdim.', a: ['iyordu-vorm(?:en)?', '-iyordu-vorm(?:en)?', 'irdi-vorm(?:en)?', '-irdi-vorm(?:en)?'],
      gen: 'Deze verleden tijd gebruik je voor de <b>achtergrond</b> van een verhaal (wat er bezig was) en voor wat je <b>vroeger gewoonlijk</b> deed: <i>het regende, ik woonde toen in Izmir</i>.',
      html: 'Je stapelt twee achtervoegsels. <b>-iyor + du</b> = was bezig: <i>gel<b>iyordu</b>m</i> (ik was aan het komen). <b>-ir + di</b> = deed vroeger altijd: <i>gel<b>irdi</b>m</i> (ik kwam altijd). Het afgeronde moment zelf staat in de verleden tijd op -di.',
      ex: [['Yağmur yağıyordu.', 'Het regende.'], ['Sen aradığında yemek yiyordum.', 'Toen je belde, was ik aan het eten.'], ['Çocukken her yaz köye giderdik.', 'Als kind gingen we elke zomer naar het dorp.'], ['Eskiden çok sigara içerdi.', 'Vroeger rookte hij veel.']] },
    perfecto: { n: 'duyulan geçmiş zaman (-miş)', t: 'Van horen zeggen (-miş)', k: 'De verleden tijd voor wat je niet zelf zag: gehoord, ontdekt of afgeleid.', a: ['van horen zeggen', 'miş-vorm(?:en)?', '-miş-vorm(?:en)?', 'miş-verleden tijd'],
      gen: 'Het Nederlands zegt <i>ik heb gegeten</i> met een hulpwerkwoord. Het Turks heeft zo’n voltooide tijd niet. Wel heeft het een aparte verleden tijd voor iets wat je <b>niet zelf hebt gezien</b>.',
      html: 'Met <b>-miş</b> (-mış, -muş, -müş) vertel je iets wat je <b>van een ander hebt gehoord</b>, wat je <b>nu pas ontdekt</b> of wat je <b>afleidt</b>: <i>Ali gel<b>miş</b></i> (Ali is blijkbaar gekomen; ik zie zijn jas). Zag je het zelf, dan zeg je <i>Ali geldi</i>. Ook sprookjes en roddels staan in deze vorm.',
      ex: [['Ali evlenmiş!', 'Ali schijnt getrouwd te zijn!'], ['Aa, kar yağmış.', 'O, het heeft gesneeuwd (zie ik nu).'], ['Çok güzel olmuş.', 'Dat is heel mooi geworden.'], ['Bir varmış, bir yokmuş …', 'Er was eens …']],
      uz: [['Uyumuşum', 'Over jezelf gebruik je -miş als je het <b>niet bewust</b> meemaakte: <i>Uyu<b>muş</b>um</i> (ik ben blijkbaar in slaap gevallen). <b>Waarom?</b> -miş zegt niet "iemand anders", maar "ik was er niet met mijn aandacht bij". Slapen, vergeten of iets per ongeluk doen ontdek je pas achteraf.'],
        ['Çok güzel olmuş', 'Bij een compliment over iets wat je voor je ziet, zeg je toch <i>olmuş</i> en niet <i>oldu</i>. <b>Waarom?</b> Je zag het maken niet; je ziet alleen het resultaat. -miş drukt precies die verrassing uit: "kijk nou, het is mooi geworden".']] },
    futuro: { n: 'gelecek zaman (-ecek)', a: ['ecek-vorm(?:en)?', '-ecek-vorm(?:en)?', 'gelecek zaman'],
      html: 'Het achtervoegsel is <b>-ecek / -acak</b> plus de persoonsuitgang: <i>gel<b>ecek</b>sin, yap<b>acak</b>lar</i>. Je gebruikt het voor plannen en voorspellingen. In spreektaal zeg je voor iets wat vaststaat ook gewoon <i>-iyor</i>: <i>Yarın geliyorum</i>.',
      table: [['', 'gelmek', 'yapmak'], ['ben', 'geleceğim', 'yapacağım'], ['sen', 'geleceksin', 'yapacaksın'], ['o', 'gelecek', 'yapacak'], ['biz', 'geleceğiz', 'yapacağız'], ['siz', 'geleceksiniz', 'yapacaksınız'], ['onlar', 'gelecekler', 'yapacaklar']],
      ex: [['Yarın geleceğim.', 'Ik kom morgen.'], ['Ne yapacaksın?', 'Wat ga je doen?'], ['Yağmur yağacak.', 'Het gaat regenen.']],
      uz: [['geleceğim, geleceğiz', 'Bij ik en wij wordt de <b>k</b> een <b>ğ</b>: <i>gelece<b>ğ</b>im</i>. <b>Waarom?</b> Een k tussen twee klinkers wordt in het Turks zacht (net als <i>çocuk → çocuğu</i>). Bij <i>geleceksin</i> volgt er een medeklinker en blijft de k hard.'],
        ['gelicem, yapıcam', 'In gesproken Turks hoor je <i>gelicem, yapıcam, gidicez</i>. Dat schrijf je alleen in appjes. <b>Waarom?</b> De zachte ğ is bijna onhoorbaar; in snel praten smelten de klinkers eromheen samen. De schrijftaal houdt de volle vorm aan.']] },
    condicional: { n: 'şart kipi (-se) · -irdi', t: 'Voorwaarde en zou (-se, -irdi)', k: 'Als … dan zou: gelse, gelirdim.', a: ['se-vorm(?:en)?', '-se-vorm(?:en)?', 'als-vorm(?:en)?', 'şart kipi'],
      html: '"Als" is geen los woord maar het achtervoegsel <b>-se / -sa</b>. Voor een echte mogelijkheid komt het na de tijd: <i>gel<b>irse</b>n</i> (als je komt). Voor iets onwerkelijks komt het direct na de stam: <i>gel<b>se</b>n</i> (als je zou komen). "Zou" in de hoofdzin is <b>-irdi</b>: <i>gel<b>irdi</b>m</i> (ik zou komen). Het woord <i>eğer</i> (als) mag ervoor, maar hoeft niet.',
      ex: [['Vaktim olursa gelirim.', 'Als ik tijd heb, kom ik.'], ['Vaktim olsa gelirdim.', 'Als ik tijd had, zou ik komen.'], ['Bilseydim söylerdim.', 'Als ik het geweten had, had ik het gezegd.'], ['Keşke burada olsan.', 'Was je maar hier.']] },
    subjuntivo: { n: 'istek kipi (-eyim, -elim, -sin)', t: 'Wensvorm (-eyim, -elim, -sin)', k: 'De vorm voor een voorstel of wens: gideyim, gidelim, gitsin.', a: ['wensvorm(?:en)?', 'wensende wijs', 'istek kipi'],
      gen: 'Met de <b>wensvorm</b> zeg je niet wat er gebeurt, maar wat je wilt of voorstelt: <i>laat ik gaan, zullen we gaan, laat hem maar komen</i>.',
      html: 'Voor <b>ik</b>: <b>-eyim</b> (<i>gid<b>eyim</b></i>, laat ik gaan). Voor <b>wij</b>: <b>-elim</b> (<i>gid<b>elim</b></i>, laten we gaan). Voor <b>hij/zij</b>: <b>-sin</b> (<i>git<b>sin</b></i>, laat hem gaan). Met <i>mi</i> wordt het een voorstel: <i>Gidelim <b>mi</b>?</i> "Ik wil dat jij …" zeg je met -me + bezitsuitgang: <i>Gel<b>meni</b> istiyorum</i>.',
      ex: [['Ben gideyim.', 'Laat ik maar gaan.'], ['Hadi gidelim!', 'Kom, laten we gaan!'], ['Çay içelim mi?', 'Zullen we thee drinken?'], ['Geçmiş olsun.', 'Beterschap (letterlijk: moge het voorbij zijn).']],
      uz: [['Gelmeni istiyorum', 'Na <i>istemek</i> (willen) volgt geen bijzin met een wensvorm, maar een naamwoord: <i>Gel<b>meni</b> istiyorum</i> (letterlijk: ik wil jouw komen). <b>Waarom?</b> Het Turks maakt van een bijzin het liefst een zelfstandig naamwoord met uitgangen. Wat je wilt, is dan gewoon het lijdend voorwerp van <i>istemek</i>.']] },
    imperativo: { n: 'emir kipi',
      html: 'De kale <b>stam</b> is de gebiedende wijs voor <i>sen</i>: <b>Gel!</b> Voor <i>siz</i> (u of jullie) komt er <b>-in</b> achter: <b>Gelin!</b>, en heel formeel <b>-iniz</b>: <b>Geliniz</b>. De ontkenning krijgt <b>-me</b>: <b>Gelme!</b> Met <i>lütfen</i> of de vraagvorm (<i>Gelir misiniz?</i>) klinkt het vriendelijker.',
      table: [['', 'kom', 'kom niet'], ['sen', 'gel', 'gelme'], ['siz', 'gelin', 'gelmeyin'], ['siz (heel formeel)', 'geliniz', 'gelmeyiniz'], ['o (laat hem …)', 'gelsin', 'gelmesin']],
      ex: [['Buraya gel!', 'Kom hier!'], ['Lütfen oturun.', 'Gaat u zitten, alstublieft.'], ['Dokunma!', 'Niet aankomen!'], ['Kapıyı kapatır mısınız?', 'Wilt u de deur dichtdoen?']] },

    /* ================= Vorm en klank ================= */
    geslacht: { n: 'cinsiyet (yok)',
      html: 'Het Turks heeft <b>geen grammaticaal geslacht</b>. Er is geen de/het, geen mannelijk of vrouwelijk, en <b>o</b> betekent hij, zij én het. Wil je het verschil toch noemen, dan zet je er een woord bij: <i>kız kardeş</i> (zus), <i>erkek kardeş</i> (broer), <i>kadın doktor</i> (vrouwelijke arts).',
      ex: [['O geldi.', 'Hij / zij is gekomen.'], ['kardeşim', 'mijn broer of zus'], ['kız kardeşim, erkek kardeşim', 'mijn zus, mijn broer']] },
    getal: { n: 'tekil ve çoğul (-ler / -lar)',
      html: 'Het meervoud maak je met <b>-ler</b> (na e, i, ö, ü) of <b>-lar</b> (na a, ı, o, u): <i>ev<b>ler</b>, kitap<b>lar</b></i>. Andere uitgangen komen erachter: <i>ev-ler-im-de</i>.',
      ex: [['ev → evler', 'huis → huizen'], ['kitap → kitaplar', 'boek → boeken'], ['üç kitap', 'drie boeken'], ['Çok insan var.', 'Er zijn veel mensen.']],
      uz: [['üç elma, çok kitap', 'Na een telwoord of na <i>çok, kaç, birkaç</i> blijft het woord <b>enkelvoud</b>: <i>üç elma</i>, niet <i>üç elmalar</i>. <b>Waarom?</b> Het telwoord zegt al dat het er meer zijn. Het Turks geeft dezelfde informatie niet twee keer.'],
        ['saatler, harfler', '<i>Saat</i> (uur) wordt <b>saatler</b> en niet <i>saatlar</i>, hoewel de laatste klinker een a is. <b>Waarom?</b> Het is een Arabisch leenwoord waarin de a "dun" wordt uitgesproken, dichter bij een e. De uitgang volgt de klank, niet de letter. Zo ook <i>harf → harfler</i>, <i>kalp → kalpler</i>.']] },
    congruentie: { n: 'uyum',
      html: 'Het Turks kent <b>weinig congruentie</b>. Een bijvoeglijk naamwoord verandert nooit: <i>güzel ev, güzel evler</i>. Aanwijzende woorden ook niet: <i>bu ev, bu evler</i>. Alleen het werkwoord past bij de persoon van het onderwerp: <i>ben geliyor<b>um</b>, sen geliyor<b>sun</b></i>.',
      ex: [['büyük ev, büyük evler', 'groot huis, grote huizen'], ['Ben geliyorum, sen geliyorsun.', 'Ik kom, jij komt.'], ['Çocuklar oynuyor.', 'De kinderen spelen.']] },
    verkleinwoord: { n: 'küçültme (-cik)',
      html: 'Het verkleinwoord maak je met <b>-cik</b> (-cık, -cuk, -cük; na een harde medeklinker -çik): <i>kedi<b>cik</b></i> (poesje), <i>anne<b>ciğim</b></i> (lief mamaatje). Het klinkt vooral <b>lief en warm</b>. Met <b>-ceğiz</b> klinkt er medelijden in door: <i>kız<b>cağız</b></i> (dat arme meisje).',
      ex: [['kedicik', 'poesje'], ['Anneciğim!', 'Lieve mama!'], ['Bir dakikacık!', 'Eén minuutje!'], ['Zavallı adamcağız.', 'Die arme man.']],
      uz: [['küçücük, ufacık, minicik', '<i>Küçük</i> wordt <b>küçücük</b> (piepklein), <i>ufak → ufacık</i>, <i>sıcak → sıcacık</i>: de laatste <b>k</b> valt weg. <b>Waarom?</b> <i>Küçük-cük</i> heeft twee harde klanken vlak na elkaar; dat struikelt. De k verdwijnt en het woord rolt weer.']] },
    vergelijking: { n: 'karşılaştırma (daha, en)',
      gen: 'Met de <b>vergrotende trap</b> vergelijk je twee dingen (<i>Istanbul is <b>groter</b> dan Ankara</i>). Met de <b>overtreffende trap</b> zeg je dat iets het meest is (<i>de <b>grootste</b> stad</i>).',
      html: 'Het bijvoeglijk naamwoord zelf verandert niet. Je zet er <b>daha</b> (meer) of <b>en</b> (meest) voor: <i><b>daha</b> büyük</i> (groter), <i><b>en</b> büyük</i> (grootst). "Dan" is de uitgang <b>-den / -dan</b> aan het woord waarmee je vergelijkt: <i>Ankara’<b>dan</b> daha büyük</i>. "Even … als" is <b>kadar</b>.',
      ex: [['İstanbul Ankara’dan daha büyük.', 'Istanbul is groter dan Ankara.'], ['Türkiye’nin en büyük şehri', 'de grootste stad van Turkije'], ['Senin kadar uzunum.', 'Ik ben even lang als jij.'], ['Bu daha ucuz.', 'Deze is goedkoper.']] },
    accent: { n: 'vurgu', k: 'Welke lettergreep je het hardst zegt. In het Turks bijna altijd de laatste.',
      gen: 'De <b>klemtoon</b> is de lettergreep die je het hardst zegt: <i>ta<b>FEL</b></i>, <i><b>AU</b>to</i>.',
      html: 'In het Turks ligt de klemtoon bijna altijd op de <b>laatste lettergreep</b>, en hij schuift mee als er een uitgang bijkomt: <i>ki<b>TAP</b>, kitap<b>LAR</b>, kitapla<b>RIM</b></i>. Het Turks schrijft geen klemtoontekens. Het dakje (<b>â, î, û</b>) geeft geen klemtoon aan, maar een lange klinker of een zachte k, g of l ervoor: <i>kâr</i> (winst) naast <i>kar</i> (sneeuw).',
      ex: [['kitap, kitaplar, kitaplarım', 'boek, boeken, mijn boeken'], ['kâr / kar', 'winst / sneeuw'], ['hâlâ / hala', 'nog steeds / tante (zus van vader)']],
      uz: [['İSTANbul, ANkara, İZmir', 'Plaatsnamen hebben de klemtoon <b>niet</b> op het eind: <i>is<b>TAN</b>bul, <b>AN</b>kara, <b>İZ</b>mir</i>. <b>Waarom?</b> Veel plaatsnamen zijn ouder dan het Turks in de streek (Grieks, Armeens, Perzisch) en hebben hun eigen klemtoon gehouden. Daarna is dat het patroon voor alle plaatsnamen geworden.'],
        ['GELme, geLİyor musun', 'De ontkenning <i>-me</i> en het vraagwoordje <i>mi</i> krijgen nooit klemtoon; die valt op de lettergreep ervoor: <i><b>GEL</b>me, geli<b>YOR</b> musun</i>. <b>Waarom?</b> Het zijn van oorsprong losse, zwakke woordjes die tegen het werkwoord aan leunen. Zulke aanhangsels blijven onbeklemtoond.']] },

    /* ================= Aanspreken ================= */
    aanspreken: { n: 'sen ve siz', t: 'Sen en siz', k: 'Jij of u zeggen in het Turks, en hoe je mensen aanspreekt.', a: ['sen en siz', 'sen/siz', 'sen of siz'],
      html: '<b>Sen</b> = jij (familie, vrienden, kinderen). <b>Siz</b> = u, én jullie. Tegen onbekenden, ouderen en op het werk zeg je <i>siz</i>. Beleefd aanspreken doe je met de <b>voornaam + Bey</b> (meneer) of <b>Hanım</b> (mevrouw): <i>Ahmet Bey, Ayşe Hanım</i>. Onbekenden spreek je vaak aan met een familiewoord: <i>abi</i> (grote broer), <i>abla</i> (grote zus), <i>teyze</i> (tante), <i>amca</i> (oom).',
      table: [['', 'informeel', 'beleefd / meervoud'], ['hoe gaat het?', 'Nasılsın?', 'Nasılsınız?'], ['kom binnen', 'Gel.', 'Gelin. / Buyurun.'], ['jouw / uw naam', 'adın', 'adınız']],
      ex: [['Nasılsın?', 'Hoe gaat het met je?'], ['Nasılsınız?', 'Hoe gaat het met u / met jullie?'], ['Ayşe Hanım, buyurun.', 'Mevrouw Ayşe, gaat uw gang.'], ['Abi, bakar mısın?', 'Meneer (letterlijk: grote broer), mag ik even?']],
      uz: [['Ahmet Bey: voornaam, niet achternaam', 'Je zegt <i>Ahmet Bey</i> en <i>Ayşe Hanım</i>, met de <b>voornaam</b>. <b>Waarom?</b> Achternamen bestaan in Turkije pas sinds 1934. De gewoonte om iemand beleefd met voornaam en titel aan te spreken is veel ouder en is gebleven. Alleen op papier staat <i>Sayın Yılmaz</i>.']] }
  }, [
    /* ================= Alleen in het Turks ================= */
    { id: 'tr-klinkerharmonie', c: 'vorm', t: 'Klinkerharmonie', a: ['klinkerharmonie', 'grote klinkerharmonie', 'kleine klinkerharmonie', 'ünlü uyumu'],
      k: 'De klinker van een uitgang past zich aan bij de laatste klinker van het woord.',
      html: '<b>Klinkerharmonie</b> betekent dat klinkers binnen één woord bij elkaar passen. Een uitgang heeft daardoor geen vaste klinker: hij neemt de kleur aan van de klinker die ervoor staat.',
      tr: { n: 'ünlü uyumu',
        html: 'Er zijn twee soorten uitgangen. <b>Tweevoudig</b> (e of a): na <i>e, i, ö, ü</i> komt <b>e</b>, na <i>a, ı, o, u</i> komt <b>a</b>: <i>ev<b>ler</b>, kitap<b>lar</b>, ev<b>de</b>, okul<b>da</b></i>. <b>Viervoudig</b> (i, ı, ü of u): na <i>e, i</i> komt <b>i</b>, na <i>a, ı</i> komt <b>ı</b>, na <i>ö, ü</i> komt <b>ü</b>, na <i>o, u</i> komt <b>u</b>: <i>ev<b>im</b>, kız<b>ım</b>, göz<b>üm</b>, okul<b>um</b></i>. Kijk altijd naar de <b>laatste klinker</b> van het woord.',
        table: [['laatste klinker', 'e / a', 'i / ı / ü / u', 'voorbeeld'], ['e, i', 'e', 'i', 'evler · evim'], ['a, ı', 'a', 'ı', 'kızlar · kızım'], ['ö, ü', 'e', 'ü', 'gözler · gözüm'], ['o, u', 'a', 'u', 'okullar · okulum']],
        ex: [['evde, okulda', 'in huis, op school'], ['evim, kızım, gözüm, okulum', 'mijn huis, mijn dochter, mijn oog, mijn school'], ['geldi, aldı, gördü, oldu', 'hij kwam, nam, zag, werd'], ['Türkiye’de, Hollanda’da', 'in Turkije, in Nederland']],
        uz: [['saatler, kalbim, harfler', 'Sommige leenwoorden krijgen een "dunne" uitgang na een a of o: <i>saat<b>ler</b>, kalb<b>im</b>, alkol<b>ü</b>, rol<b>ü</b></i>. <b>Waarom?</b> In deze Arabische en Franse woorden wordt de laatste klinker of de l dun uitgesproken, voor in de mond. De uitgang luistert naar de klank, niet naar de letter.'],
          ['-iyor, -ken, -ki veranderen niet', 'Een paar uitgangen doen niet mee: <i>geli<b>yor</b></i> (nooit -yör), <i>yapar<b>ken</b></i>, <i>yarın<b>ki</b></i>. <b>Waarom?</b> Het waren vroeger losse woorden (<i>yorır, iken, ki</i>). Ze zijn later aan het woord vastgegroeid en hebben hun eigen klinker gehouden.'],
          ['elma, kardeş, anne', 'Ook sommige gewone woorden hebben "gemengde" klinkers: <i>elma, kardeş, anne, hangi</i>. <b>Waarom?</b> Deze woorden zijn in de loop van de tijd van klank veranderd (<i>alma → elma, karındaş → kardeş, ana → anne</i>). Voor de uitgang maakt het niet uit: die kijkt alleen naar de laatste klinker.']] },
      rel: ['tr-achtervoegsel', 'tr-medeklinker', 'tr-naamval'] },

    { id: 'tr-achtervoegsel', c: 'vorm', t: 'Achtervoegsel (plaktaal)', a: ['achtervoegsel(?:s)?', 'plaktaal', 'agglutinatie', 'agglutinerende? taal', 'suffix(?:en)?'],
      k: 'Een stukje dat je achter een woord plakt en dat één ding betekent: -ler, -im, -de.',
      html: 'Een <b>achtervoegsel</b> is een stukje dat achter een woord komt en er iets aan toevoegt. In het Nederlands: <i>vriend → vriend<b>elijk</b> → vriendelijk<b>heid</b></i>.',
      tr: { n: 'ek (sondan eklemeli dil)',
        html: 'Het Turks is een <b>plaktaal</b>: bijna alles wat het Nederlands met losse woordjes zegt, plak je achter het woord, in een <b>vaste volgorde</b>. Elk achtervoegsel betekent één ding. Bij een zelfstandig naamwoord: <b>woord + meervoud + bezit + naamval</b>. Bij een werkwoord: <b>stam + ontkenning + tijd + persoon</b>. Lees een lang woord dus van links naar rechts, stukje voor stukje.',
        table: [['woord', 'opbouw', 'betekenis'], ['evlerimizde', 'ev-ler-imiz-de', 'in onze huizen'], ['arkadaşlarımla', 'arkadaş-lar-ım-la', 'met mijn vrienden'], ['gelmeyeceğim', 'gel-me-yeceğ-im', 'ik zal niet komen'], ['konuşabiliyor musun', 'konuş-abil-iyor mu-sun', 'kun je praten?']],
        ex: [['ev → evler → evlerim → evlerimde', 'huis → huizen → mijn huizen → in mijn huizen'], ['gel → geldi → gelmedi → gelmediler', 'kom → hij kwam → hij kwam niet → ze kwamen niet'], ['Hollandalıyım.', 'Ik ben Nederlander (Hollanda-lı-yım).']] },
      rel: ['tr-klinkerharmonie', 'tr-naamval', 'tr-bindklank'] },

    { id: 'tr-naamval', c: 'vorm', t: 'Naamval', a: ['naamval(?:len)?', 'naamvalsuitgang(?:en)?', 'accusatief', 'datief', 'locatief', 'ablatief', 'genitief', 'i-naamval', 'e-naamval', 'de-naamval', 'den-naamval'],
      k: 'Een uitgang die zegt welke rol een woord in de zin heeft: naar, in, van, uit.',
      html: 'Een <b>naamval</b> is een uitgang aan een woord die laat zien wat de rol van dat woord in de zin is. Het Nederlands doet dat met voorzetsels (<i>in</i> huis, <i>naar</i> huis) en heeft alleen nog resten van naamvallen: <i>’s avonds, ter plekke</i>.',
      tr: { n: 'hâl ekleri (durum ekleri)',
        html: 'Het Turks heeft <b>zes naamvallen</b>. De uitgangen volgen de klinkerharmonie, en na een harde medeklinker (<i>f, s, t, k, ç, ş, h, p</i>) wordt d een t: <i>sokak<b>ta</b>, sokak<b>tan</b></i>. Na een klinker komt er een bindklank tussen: <i>araba<b>y</b>ı, araba<b>y</b>a, araba<b>n</b>ın</i>.',
        table: [['naamval', 'uitgang', 'betekenis', 'ev', 'okul'], ['kaal', '–', 'onderwerp', 'ev', 'okul'], ['-i', '-i / -ı / -u / -ü', 'hét … (lijdend voorwerp)', 'evi', 'okulu'], ['-e', '-e / -a', 'naar, aan', 'eve', 'okula'], ['-de', '-de / -da', 'in, op, bij', 'evde', 'okulda'], ['-den', '-den / -dan', 'van, uit, dan', 'evden', 'okuldan'], ['-in', '-in / -ın / -un / -ün', 'van (bezitter)', 'evin', 'okulun']],
        ex: [['Eve gidiyorum.', 'Ik ga naar huis.'], ['Evdeyim.', 'Ik ben thuis.'], ['Evden çıktım.', 'Ik ben van huis vertrokken.'], ['Evin kapısı', 'de deur van het huis']],
        uz: [['-den korkmak, -e bakmak, -i sevmek', 'Elk werkwoord vraagt zijn eigen naamval, en die is niet altijd wat je verwacht: <i>köpek<b>ten</b> korkmak</i> (bang zijn voor), <i>bana bak</i> (kijk naar mij), <i>-<b>e</b> başlamak</i> (beginnen met). <b>Waarom?</b> De naamval volgt het Turkse beeld: angst komt <i>van</i> iets vandaan, kijken gaat <i>naar</i> iets toe. Leer een werkwoord daarom samen met zijn naamval.'],
          ['su → suyun, ne → neyin', 'Na een klinker is de bezitter-uitgang -nin (<i>araba<b>nın</b></i>), maar <i>su</i> en <i>ne</i> krijgen <b>-yun / -yin</b>: <i>su<b>yun</b>, ne<b>yin</b></i>. <b>Waarom?</b> <i>Su</i> was vroeger <i>suv</i>; die oude medeklinker leeft voort als y. <i>Ne</i> heeft zich daarbij aangesloten.']] },
      rel: ['tr-klinkerharmonie', 'tr-achterzetsel', 'tr-bezitsuitgang', 'lv', 'mv', 'vz'] },

    { id: 'tr-medeklinker', c: 'vorm', t: 'Medeklinkerverandering', a: ['medeklinkerverandering(?:en)?', 'medeklinkerverzachting', 'medeklinkerverharding', 'verzachting', 'harde medeklinker(?:s)?', 'zachte medeklinker(?:s)?', 'ünsüz yumuşaması'],
      k: 'p, ç, t, k worden b, c, d, ğ vóór een klinker; d wordt t na een harde medeklinker.',
      html: 'Bij een <b>medeklinkerverandering</b> past een medeklinker zich aan zijn buren aan, zodat het woord makkelijker uit te spreken is. In het Nederlands schrijf je <i>hui<b>s</b> → hui<b>z</b>en</i>.',
      tr: { n: 'ünsüz yumuşaması ve benzeşmesi',
        html: 'Twee regels. <b>1. Verzachting:</b> eindigt een woord van meer dan één lettergreep op <b>p, ç, t, k</b> en komt er een klinker achter, dan worden die <b>b, c, d, ğ</b>: <i>kita<b>p</b> → kita<b>b</b>ı</i>, <i>ağa<b>ç</b> → ağa<b>c</b>ı</i>, <i>kâğı<b>t</b> → kâğı<b>d</b>ı</i>, <i>çocu<b>k</b> → çocu<b>ğ</b>u</i>. <b>2. Verharding:</b> na <b>f, s, t, k, ç, ş, h, p</b> wordt een d een <b>t</b> en een c een <b>ç</b>: <i>kitap<b>ta</b>, sokak<b>tan</b>, git<b>ti</b>, Türk<b>çe</b></i>. Ezelsbruggetje voor die acht letters: <i><b>F</b>ı<b>st</b>ı<b>kç</b>ı <b>Ş</b>a<b>h</b>a<b>p</b></i>.',
        table: [['', 'kaal', 'met klinker'], ['p → b', 'kitap', 'kitabım'], ['ç → c', 'ağaç', 'ağacı'], ['t → d', 'kâğıt', 'kâğıdı'], ['k → ğ', 'çocuk', 'çocuğum']],
        ex: [['kitap → kitabım', 'boek → mijn boek'], ['çocuk → çocuğu', 'kind → zijn kind'], ['sokakta, kitapta', 'op straat, in het boek'], ['Türkçe, Almanca', 'Turks, Duits']],
        uz: [['at → atı, saç → saçı, top → topu', 'Woorden van <b>één lettergreep</b> blijven meestal hard: <i>at → atı</i> (paard), <i>saç → saçı</i> (haar), <i>top → topu</i> (bal). <b>Waarom?</b> De verzachting ontstond vooral na een lange klinker en in langere woorden. De meeste korte woorden hadden een korte klinker, en daar bleef de medeklinker hard. Een paar korte woorden met een oude lange klinker verzachten wél: <i>ad → adı</i> (naam), <i>kap → kabı</i>, <i>uç → ucu</i>.'],
          ['saat → saati, bilet → bileti', 'Veel leenwoorden verzachten niet: <i>saat<b>i</b>, bilet<b>i</b>, devlet<b>i</b>, hukuk<b>u</b></i>. <b>Waarom?</b> De regel is in het Turks zelf ontstaan; woorden die later uit het Arabisch of Frans kwamen, hielden hun eigen medeklinker.'],
          ['renk → rengi', 'Eindigt een woord op <b>-nk</b>, dan wordt de k een <b>g</b> en geen ğ: <i>renk → ren<b>g</b>i</i>, <i>denk → den<b>g</b>i</i>. <b>Waarom?</b> Een ğ kan alleen tussen twee klinkers staan. Na een n is dat niet zo, dus blijft er een gewone zachte g over.']] },
      rel: ['tr-klinkerharmonie', 'tr-bindklank'] },

    { id: 'tr-bindklank', c: 'vorm', t: 'Bindklank (y, n, s)', a: ['bindklank(?:en)?', 'tussenklank(?:en)?', 'bindletter(?:s)?', 'kaynaştırma'],
      k: 'Een extra medeklinker tussen twee klinkers: araba-y-ı, araba-s-ı, evi-n-de.',
      html: 'Een <b>bindklank</b> is een extra letter die tussen twee delen van een woord komt om het uitspreekbaar te houden. In het Nederlands: <i>zee-<b>ë</b>n</i> schrijf je zo, en je zegt <i>koe<b>i</b>en</i>.',
      tr: { n: 'kaynaştırma harfleri (y, ş, s, n)',
        html: 'In het Turks mogen twee klinkers niet tegen elkaar botsen. Eindigt het woord op een klinker en begint de uitgang ook met een klinker, dan komt er een medeklinker tussen. <b>y</b> is de gewone: <i>araba<b>y</b>ı, araba<b>y</b>a, oku<b>y</b>acak</i>. <b>s</b> hoort bij "zijn/haar": <i>araba<b>s</b>ı</i>. <b>n</b> hoort bij "van" en komt ná een bezitsuitgang van de 3e persoon: <i>araba<b>n</b>ın, evi<b>n</b>de, arabası<b>n</b>a</i>. <b>ş</b> staat alleen bij "elk … stuks": <i>iki<b>ş</b>er</i>.',
        table: [['bindklank', 'wanneer', 'voorbeeld'], ['y', 'naamval of tijd na een klinker', 'arabayı · Ali’ye · okuyor'], ['s', 'bezit 3e persoon na een klinker', 'arabası · annesi'], ['n', 'bezitter (-in) na een klinker; na bezit 3e persoon', 'arabanın · evinde'], ['ş', 'verdelend telwoord', 'ikişer · altışar']],
        ex: [['Arabayı gördüm.', 'Ik heb de auto gezien.'], ['Ali’nin arabası', 'de auto van Ali'], ['Arabasında oturuyor.', 'Hij zit in zijn auto.'], ['İkişer elma aldık.', 'We namen elk twee appels.']],
        uz: [['evinde: jouw huis of zijn huis?', '<i>Evinde</i> kan "in jouw huis" (ev-in-de) én "in zijn huis" (ev-i-n-de) zijn. <b>Waarom?</b> De bindklank n na "zijn" valt toevallig samen met de uitgang -in van "jouw". Wil je duidelijk zijn, dan zet je <i>senin</i> of <i>onun</i> ervoor.'],
          ['su → suyu', '<i>Su</i> krijgt als bezit <b>-yu</b> en niet -su: <i>portakal su<b>y</b>u</i> (sinaasappelsap). <b>Waarom?</b> Het woord eindigde vroeger op een medeklinker (<i>suv</i>). Die is een y geworden, dus de bindklank s is niet nodig.']] },
      rel: ['tr-achtervoegsel', 'tr-bezitsuitgang', 'tr-naamval'] },

    { id: 'tr-bezitsuitgang', c: 'vorm', t: 'Bezitsuitgang en bezitsconstructie', a: ['bezitsuitgang(?:en)?', 'bezitsconstructie(?:s)?', 'bezitsvorm(?:en)?', 'isim tamlaması', 'iyelik eki'],
      k: 'Van wie iets is, plak je aan het bezit: evim, mijn huis. Ali’nin evi, het huis van Ali.',
      html: 'In het Nederlands zeg je bezit met een los woord: <i><b>mijn</b> huis, het huis <b>van</b> Ali</i>. Een <b>bezitsuitgang</b> doet hetzelfde, maar dan als stukje achter het woord.',
      tr: { n: 'iyelik eki · isim tamlaması',
        html: 'Het bezit krijgt altijd een uitgang: <i>ev<b>im</b>, ev<b>in</b>, ev<b>i</b>, ev<b>imiz</b>, ev<b>iniz</b>, ev<b>leri</b></i>. Noem je de bezitter, dan krijgt die <b>-in</b> en het bezit <b>-(s)i</b>: <i>Ali’<b>nin</b> ev<b>i</b></i> (letterlijk: van-Ali zijn-huis). Is het geen echt bezit maar een <b>soort</b>, dan vervalt de -in: <i>otobüs durağ<b>ı</b></i> (bushalte), <i>Türk kahve<b>si</b></i> (Turkse koffie).',
        table: [['', 'bezitter', 'bezit', 'betekenis'], ['bepaald', 'Ali’nin', 'arabası', 'de auto van Ali'], ['bepaald', 'evin', 'kapısı', 'de deur van het huis'], ['soort', 'ev', 'kapısı', 'huisdeur'], ['soort', 'çocuk', 'odası', 'kinderkamer']],
        ex: [['Annemin adı Fatma.', 'De naam van mijn moeder is Fatma.'], ['otobüs durağı', 'bushalte'], ['Türk kahvesi', 'Turkse koffie'], ['Arabam yok.', 'Ik heb geen auto.']],
        uz: [['onların evi', 'Bij "hun" zeg je meestal <i>onların ev<b>i</b></i> en niet <i>evleri</i>. <b>Waarom?</b> <i>Evleri</i> kan vier dingen betekenen (hun huis, hun huizen, zijn huizen). Omdat <i>onların</i> het meervoud al noemt, laat het Turks de tweede -ler weg.'],
          ['altın yüzük, tahta masa', 'Bij een <b>materiaal</b> krijgt geen van beide woorden een uitgang: <i>altın yüzük</i> (gouden ring), <i>tahta masa</i> (houten tafel). <b>Waarom?</b> Het materiaal werkt hier als bijvoeglijk naamwoord: het zegt hoe de ring is, niet van wie of van welke soort hij is.']] },
      rel: ['bez', 'tr-naamval', 'tr-bindklank', 'tr-varyok'] },

    { id: 'tr-achterzetsel', c: 'soort', t: 'Achterzetsel', a: ['achterzetsel(?:s)?', 'postpositie(?:s)?'],
      k: 'Een voorzetsel dat achter het woord staat: senin için, voor jou.',
      html: 'Een <b>achterzetsel</b> doet hetzelfde als een voorzetsel, maar staat <b>achter</b> het woord waar het bij hoort. Het Nederlands kent er een paar: <i>de hele dag <b>door</b>, de berg <b>op</b></i>.',
      tr: { n: 'edat (ilgeç)',
        html: 'Elk achterzetsel vraagt een vaste <b>naamval</b> van het woord ervoor. Zonder uitgang: <b>için</b> (voor), <b>ile</b> (met), <b>gibi</b> (zoals), <b>kadar</b> (zoveel als). Met <b>-e</b>: <b>göre</b> (volgens), <b>kadar</b> (tot), <b>rağmen</b> (ondanks), <b>doğru</b> (richting). Met <b>-den</b>: <b>önce</b> (voor, eerder), <b>sonra</b> (na), <b>beri</b> (sinds), <b>dolayı</b> (vanwege). Plaats zeg je met een zelfstandig naamwoord: <i>masanın <b>üstünde</b></i> (op de tafel).',
        table: [['naamval', 'achterzetsels', 'voorbeeld'], ['kaal', 'için, ile, gibi, kadar', 'annem için'], ['-e', 'göre, kadar, rağmen, doğru', 'bana göre · akşama kadar'], ['-den', 'önce, sonra, beri, dolayı', 'yemekten sonra']],
        ex: [['Bu senin için.', 'Dit is voor jou.'], ['Bana göre haklısın.', 'Volgens mij heb je gelijk.'], ['Yemekten sonra çay içelim.', 'Laten we na het eten thee drinken.'], ['Saat beşe kadar buradayım.', 'Ik ben hier tot vijf uur.']],
        uz: [['benim için, senin gibi, onunla', 'Na een zelfstandig naamwoord staat <i>için, gibi, ile</i> zonder uitgang (<i>Ali için</i>), maar een voornaamwoord krijgt <b>-in</b>: <i>ben<b>im</b> için, sen<b>in</b> gibi, on<b>un</b>la</i>. <b>Waarom?</b> Deze achterzetsels waren vroeger zelfstandige naamwoorden met een bezitsuitgang (<i>için</i> betekende "het binnenste ervan"). Bij voornaamwoorden is de oude bezitter-vorm bewaard gebleven. Alleen <i>onlar</i> doet niet mee: <i>onlar için</i>.'],
          ['ile → -le / -la', '<i>İle</i> (met) wordt meestal aan het woord vastgeplakt als <b>-le / -la</b>, na een klinker <b>-yle / -yla</b>: <i>arkadaşım<b>la</b>, araba<b>yla</b></i>. <b>Waarom?</b> Het woord wordt zo vaak gebruikt dat het is afgesleten tot een achtervoegsel. Sindsdien doet het ook mee aan de klinkerharmonie.']] },
      rel: ['vz', 'tr-naamval'] },

    { id: 'tr-bredetijd', c: 'tijd', t: 'Brede tijd (-ir)', a: ['brede tijd', 'geniş zaman', 'aorist(?:us)?', 'ir-vorm(?:en)?', '-ir-vorm(?:en)?'],
      k: 'De tijd voor gewoontes, algemene waarheden, beloftes en beleefde vragen: gelirim.',
      html: 'De <b>brede tijd</b> zegt niet wat er nu gebeurt, maar wat <b>altijd of gewoonlijk</b> zo is. Het Nederlands gebruikt daarvoor gewoon de tegenwoordige tijd: <i>ik drink elke ochtend koffie, water kookt bij honderd graden</i>.',
      tr: { n: 'geniş zaman (-r, -ir, -er)',
        html: 'Je gebruikt de brede tijd voor <b>gewoontes</b> (<i>Her sabah kahve iç<b>er</b>im</i>), <b>algemene waarheden</b>, <b>beloftes en aanbiedingen</b> (<i>Ben yap<b>ar</b>ım</i>, ik doe het wel) en <b>beleefde vragen</b> (<i>Bakar mısınız?</i>). Vorm: na een klinker <b>-r</b> (<i>oku<b>r</b></i>), na een stam van één lettergreep <b>-er / -ar</b> (<i>yap<b>ar</b>, gid<b>er</b></i>), na een langere stam <b>-ir</b> (<i>konuş<b>ur</b>, çalış<b>ır</b></i>).',
        table: [['', 'gelmek', 'niet'], ['ben', 'gelirim', 'gelmem'], ['sen', 'gelirsin', 'gelmezsin'], ['o', 'gelir', 'gelmez'], ['biz', 'geliriz', 'gelmeyiz'], ['siz', 'gelirsiniz', 'gelmezsiniz'], ['onlar', 'gelirler', 'gelmezler']],
        ex: [['Her sabah kahve içerim.', 'Ik drink elke ochtend koffie.'], ['Su yüz derecede kaynar.', 'Water kookt bij honderd graden.'], ['Bakar mısınız?', 'Mag ik u even storen? (tegen de ober)'], ['Teşekkür ederim.', 'Dank je wel.']],
        uz: [['alır, gelir, olur', 'Dertien korte werkwoorden krijgen <b>-ir</b> in plaats van -er/-ar: <i>alır, gelir, olur, verir, bilir, görür, kalır, bulur, durur, varır, vurur, sanır, ölür</i>. <b>Waarom?</b> Ze eindigen allemaal op <i>l, r</i> of <i>n</i> en horen bij de meest gebruikte woorden van de taal. In zulke woorden blijft een oude vorm het langst bewaard.'],
          ['gelmez, gelmem', 'De ontkenning is <b>-mez</b>, en bij ik en wij valt de z weg: <i>gel<b>mem</b>, gel<b>meyiz</b></i>. <b>Waarom?</b> <i>-mez</i> is een oude zelfstandige ontkenning, niet -me + -ir. Bij ik en wij is de z in de uitspraak weggesleten vóór de persoonsuitgang.']] },
      rel: ['presente', 'tijdwijs', 'tr-kunnen'] },

    { id: 'tr-varyok', c: 'zin', t: 'Var en yok (er is, hebben)', a: ['var en yok', 'var/yok', 'var of yok'],
      k: 'Er is / er is niet. Ook de Turkse manier om "hebben" te zeggen.',
      html: 'Het Nederlands heeft twee werkwoorden: <i>er <b>is</b> melk</i> en <i>ik <b>heb</b> een auto</i>. Sommige talen zeggen allebei met "er is".',
      tr: { n: 'var · yok',
        html: '<b>Var</b> = er is, <b>yok</b> = er is niet. Ze staan aan het eind van de zin en veranderen niet: <i>Evde süt <b>var</b></i>. Het Turks heeft <b>geen werkwoord "hebben"</b>. Je zegt: <i>mijn auto is er</i> = <i>Araba<b>m</b> var</i>. De bezitter herken je aan de bezitsuitgang. Verleden tijd: <i>var<b>dı</b>, yok<b>tu</b></i>. Vraag: <i>var <b>mı</b>?</i>',
        ex: [['Evde süt var mı?', 'Is er melk in huis?'], ['Arabam var.', 'Ik heb een auto.'], ['Vaktim yok.', 'Ik heb geen tijd.'], ['Dün çok iş vardı.', 'Gisteren was er veel werk.']],
        uz: [['yok is niet değil', '<i>Yok</i> ontkent dat iets <b>bestaat of aanwezig is</b>; <i>değil</i> ontkent <b>wat iets is</b>: <i>Ali evde <b>yok</b></i> (Ali is er niet), <i>Ali evde <b>değil</b></i> (Ali is niet thuis, maar ergens anders). <b>Waarom?</b> <i>Yok</i> is het tegenovergestelde van <i>var</i> (er is), <i>değil</i> hoort bij zinnen met "zijn". Het zijn twee verschillende soorten zinnen.'],
          ['bende var', 'Naast <i>Kalemim var</i> (ik heb een pen, die is van mij) bestaat <i>Bende kalem var</i> (ik heb een pen bij me). <b>Waarom?</b> De bezitsuitgang zegt van wie iets is; de plaatsnaamval <i>-de</i> zegt alleen waar het nu is. Een geleende pen heb je <i>bende</i>.']] },
      rel: ['tr-bezitsuitgang', 'ontkenning'] },

    { id: 'tr-woordvolgorde', c: 'zin', t: 'Woordvolgorde', a: ['woordvolgorde', 'zinsvolgorde', 'zinsbouw', 'devrik cümle'],
      k: 'In het Turks staat het werkwoord achteraan: onderwerp, de rest, werkwoord.',
      html: 'De <b>woordvolgorde</b> is de volgorde van de zinsdelen. In een Nederlandse hoofdzin staat de persoonsvorm op de tweede plaats: <i>Ik <b>drink</b> vandaag thee</i>.',
      tr: { n: 'söz dizimi (özne – nesne – yüklem)',
        html: 'De Turkse basisvolgorde is <b>onderwerp – tijd – plaats – voorwerp – werkwoord</b>. Het werkwoord staat <b>achteraan</b>. Alles wat iets over een ander woord zegt, staat ervóór: het bijvoeglijk naamwoord vóór het zelfstandig naamwoord, de bezitter vóór het bezit, de bijzin vóór de hoofdzin. Het belangrijkste woord (de nadruk) zet je <b>vlak voor het werkwoord</b>.',
        ex: [['Ben bugün evde çay içiyorum.', 'Ik drink vandaag thuis thee.'], ['Ali kitabı Ayşe’ye verdi.', 'Ali gaf het boek aan Áyşe.'], ['Ali Ayşe’ye kitabı verdi.', 'Ali gaf Ayşe het bóek.'], ['Dün gelen adam', 'de man die gisteren kwam']],
        uz: [['Geliyorum ben! (omgekeerde zin)', 'In spreektaal en in liedjes staat het werkwoord vaak <b>niet</b> achteraan: <i>Geliyorum ben!</i>, <i>Çok güzel bu ev.</i> Dat heet een <i>devrik cümle</i>. <b>Waarom?</b> Wat de spreker het eerst kwijt wil, komt eerst; de rest volgt als toelichting. Omdat de naamvallen de rollen aangeven, blijft de zin toch duidelijk. In geschreven, formeel Turks doe je dit niet.']] },
      rel: ['pv', 'bijzin', 'tr-naamval'] },

    { id: 'tr-kunnen', c: 'ww', t: 'Kunnen en mogen (-ebil)', a: ['ebil-vorm(?:en)?', '-ebil-vorm(?:en)?', 'kunnen-vorm(?:en)?', 'yeterlilik'],
      k: 'Kunnen en mogen zit in het werkwoord: gelebilirim, ik kan komen.',
      html: 'Het Nederlands gebruikt een apart werkwoord: <i>ik <b>kan</b> komen, <b>mag</b> ik binnenkomen?</i> In sommige talen zit "kunnen" als stukje in het werkwoord zelf.',
      tr: { n: 'yeterlilik (-ebil / -abil)',
        html: '"Kunnen" en "mogen" zijn in het Turks het achtervoegsel <b>-ebil / -abil</b> direct na de stam, meestal met de brede tijd: <i>gel<b>ebil</b>irim</i> (ik kan komen), <i>Gir<b>ebil</b>ir miyim?</i> (mag ik binnenkomen?). Ook "het zou kunnen": <i>Yağmur yağ<b>abil</b>ir</i> (het kan gaan regenen).',
        table: [['', 'kan', 'kan niet'], ['ben', 'gelebilirim', 'gelemem'], ['sen', 'gelebilirsin', 'gelemezsin'], ['o', 'gelebilir', 'gelemez'], ['biz', 'gelebiliriz', 'gelemeyiz'], ['siz', 'gelebilirsiniz', 'gelemezsiniz'], ['onlar', 'gelebilirler', 'gelemezler']],
        ex: [['Türkçe konuşabiliyorum.', 'Ik kan Turks spreken.'], ['Girebilir miyim?', 'Mag ik binnenkomen?'], ['Yarın gelemem.', 'Ik kan morgen niet komen.'], ['Bana yardım edebilir misiniz?', 'Kunt u me helpen?']],
        uz: [['gelemem, niet gelebilmem', 'De ontkenning is <b>-eme / -ama</b>, zonder -bil: <i>gel<b>eme</b>m, yap<b>ama</b>dım</i>. <b>Waarom?</b> <i>-ebil</i> komt van het werkwoord <i>bilmek</i> (weten, kunnen). Voor "niet kunnen" had het oude Turks een ander werkwoordje, <i>u-</i> (in staat zijn): <i>gel-e u-ma</i> werd <i>geleme</i>. Daarom lijken de twee vormen niet op elkaar.'],
          ['gelmeyebilir', '<i>Gel<b>meyebilir</b></i> bestaat ook, maar betekent iets anders: "het kan zijn dat hij niet komt". <b>Waarom?</b> Hier ontkent <i>-me</i> alleen het komen, en <i>-ebil</i> zegt daarna dat dat mogelijk is. De volgorde van de achtervoegsels bepaalt de betekenis.']] },
      rel: ['tr-bredetijd', 'tr-achtervoegsel'] },

    { id: 'tr-laten', c: 'ww', t: 'Laten-vorm (-dir, -t)', a: ['laten-vorm(?:en)?', 'causatie(?:f|ve|ven)', 'ettirgen', 'dir-vorm(?:en)?', '-dir-vorm(?:en)?'],
      k: 'Iemand iets laten doen: yaptırmak, laten maken.',
      html: 'Met <b>laten</b> zeg je dat je iets niet zelf doet, maar een ander het laat doen of dat je ervoor zorgt dat het gebeurt: <i>ik <b>laat</b> mijn haar knippen, ik maak de baby <b>aan het lachen</b></i>.',
      tr: { n: 'ettirgen çatı (-dir, -t, -ir)',
        html: 'Het Turks plakt een achtervoegsel aan de stam. Het gewone is <b>-dir</b> (-dır, -dur, -dür, na een harde medeklinker -tir): <i>yap<b>tır</b>mak</i> (laten maken), <i>öl<b>dür</b>mek</i> (doden, letterlijk: laten sterven). Na een stam van meer lettergrepen op een klinker, <i>r</i> of <i>l</i> is het <b>-t</b>: <i>bekle<b>t</b>mek</i> (laten wachten), <i>anla<b>t</b>mak</i> (uitleggen, letterlijk: laten begrijpen). Wie het echt doet, krijgt <b>-e</b>: <i>Saçımı kuaför<b>e</b> kestirdim</i>.',
        ex: [['Saçımı kestirdim.', 'Ik heb mijn haar laten knippen.'], ['Seni beklettim, özür dilerim.', 'Ik heb je laten wachten, sorry.'], ['Arabayı tamir ettirdik.', 'We hebben de auto laten repareren.'], ['Beni güldürdün.', 'Je hebt me aan het lachen gemaakt.']],
        uz: [['içirmek, pişirmek, çıkarmak', 'Een groep korte werkwoorden krijgt <b>-ir</b> of <b>-er</b> in plaats van -dir: <i>iç → iç<b>ir</b></i> (laten drinken), <i>piş → piş<b>ir</b></i> (koken), <i>düş → düş<b>ür</b></i> (laten vallen), <i>çık → çık<b>ar</b></i> (eruit halen). <b>Waarom?</b> Dit zijn de oudste laten-vormen van de taal. Bij heel gewone werkwoorden is de oude uitgang gebleven; alle nieuwere krijgen -dir.'],
          ['göstermek, getirmek', '<i>Görmek</i> (zien) wordt <b>göstermek</b> (laten zien) en <i>gelmek</i> (komen) wordt <b>getirmek</b> (brengen). <b>Waarom?</b> Deze twee zijn zo oud en zo veel gebruikt dat ze tot eigen woorden zijn versleten. Je leert ze het best als losse woorden.']] },
      rel: ['passief', 'tr-achtervoegsel'] },

    { id: 'tr-moeten', c: 'tijd', t: 'Moeten (-meli, lazım, zorunda)', a: ['meli-vorm(?:en)?', '-meli-vorm(?:en)?', 'gereklilik'],
      k: 'Moeten zeg je met -meli, met lazım of met zorunda.',
      html: 'Het Nederlands heeft één werkwoord, <i>moeten</i>, voor advies (<i>je moet meer slapen</i>) en voor dwang (<i>ik moet werken</i>). Andere talen maken daar verschil tussen.',
      tr: { n: 'gereklilik (-meli / -malı)',
        html: 'Drie manieren. <b>-meli / -malı</b> is advies of eigen overtuiging: <i>Git<b>meli</b>yim</i> (ik moet echt gaan). <b>-me + bezitsuitgang + lazım / gerek</b> is neutraal "het is nodig": <i>Git<b>mem lazım</b></i>. <b>-mek zorunda</b> is dwang van buiten: <i>Çalış<b>mak zorunda</b>yım</i> (ik ben verplicht te werken).',
        ex: [['Daha çok su içmelisin.', 'Je moet meer water drinken.'], ['Gitmem lazım.', 'Ik moet gaan.'], ['Yarın çalışmak zorundayım.', 'Ik moet morgen werken (ik kan er niet onderuit).'], ['Bunu yapmamalısın.', 'Dat moet je niet doen.']],
        uz: [['gitmemeliyim en gitmek zorunda değilim', '<i>Git<b>me</b>meliyim</i> = ik moet <b>niet</b> gaan (het is beter van niet). <i>Gitmek zorunda <b>değilim</b></i> = ik <b>hoef niet</b> te gaan. <b>Waarom?</b> In het eerste geval ontkent <i>-me</i> het gaan zelf, in het tweede ontkent <i>değil</i> de verplichting. Het Nederlands doet precies hetzelfde met <i>niet moeten</i> en <i>niet hoeven</i>.']] },
      rel: ['tijdwijs', 'infinitief'] }
  ]);
})(window.SPT);
